{"file_path":"src/parse.js","content":"/** URI template parsing into literal and expression parts. */

/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATOR_CHARS = new Set(['+', '#', '.', '/', ';', '?', '&']);
const RESERVED_OPERATOR_CHARS = new Set(['=', ',', '!', '@', '|']);

const NAME_CHAR = '(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})';
const NAME_RE = new RegExp(`^${NAME_CHAR}+(?:\\.${NAME_CHAR}+)*$`);
const MODIFIER_RE = /^[1-9][0-9]{0,3}$/;

function parseVarspec(spec, openIndex) {
  if (spec === '') throw new UriTemplateError('empty variable specification', openIndex);

  let namePart;
  let explode = false;
  let maxLength = null;
  let modPart = null;

  if (spec.endsWith('*')) {
    namePart = spec.slice(0, -1);
    explode = true;
  } else if (spec.includes(':')) {
    const colonIndex = spec.indexOf(':');
    namePart = spec.slice(0, colonIndex);
    modPart = spec.slice(colonIndex + 1);
  } else {
    namePart = spec;
  }

  if (!NAME_RE.test(namePart)) {
    throw new UriTemplateError(`invalid variable name '${namePart}'`, openIndex);
  }

  if (modPart !== null) {
    if (!MODIFIER_RE.test(modPart)) {
      throw new UriTemplateError(`invalid prefix modifier ':${modPart}'`, openIndex);
    }
    maxLength = Number(modPart);
  }

  return { name: namePart, explode, maxLength };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  if (template === '') return [];

  const parts = [];
  let literalBuf = '';
  let i = 0;

  const flushLiteral = () => {
    if (literalBuf !== '') {
      parts.push({ type: 'literal', value: literalBuf });
      literalBuf = '';
    }
  };

  while (i < template.length) {
    const ch = template[i];
    if (ch === '{') {
      const openIndex = i;
      const close = template.indexOf('}', i + 1);
      if (close === -1) throw new UriTemplateError('unterminated expression', openIndex);
      const content = template.slice(openIndex + 1, close);
      if (content === '') throw new UriTemplateError('empty expression', openIndex);

      let operator = '';
      let rest = content;
      const first = content[0];
      if (OPERATOR_CHARS.has(first)) {
        operator = first;
        rest = content.slice(1);
      } else if (RESERVED_OPERATOR_CHARS.has(first)) {
        throw new UriTemplateError(`reserved operator '${first}'`, openIndex);
      }

      if (rest === '') throw new UriTemplateError('empty variable specification', openIndex);

      const specs = rest.split(',');
      const variables = specs.map((spec) => parseVarspec(spec, openIndex));

      flushLiteral();
      parts.push({ type: 'expression', operator, variables });
      i = close + 1;
    } else if (ch === '}') {
      throw new UriTemplateError(`unexpected '}'`, i);
    } else {
      literalBuf += ch;
      i += 1;
    }
  }

  flushLiteral();
  return parts;
}
"}

