import { UriTemplateError, parse } from './parse.js';

const UNRESERVED = /[A-Za-z0-9\-._~]/;
const RESERVED_CHARS = new Set([...":/?#[]@!$&'()*+,;="]);
const HEX = /^[0-9A-Fa-f]$/;

const OPERATORS = {
  '': { prefix: '', sep: ',', named: false, ifEmpty: '', reservedEncode: false },
  '+': { prefix: '', sep: ',', named: false, ifEmpty: '', reservedEncode: true },
  '#': { prefix: '#', sep: ',', named: false, ifEmpty: '', reservedEncode: true },
  '.': { prefix: '.', sep: '.', named: false, ifEmpty: '', reservedEncode: false },
  '/': { prefix: '/', sep: '/', named: false, ifEmpty: '', reservedEncode: false },
  ';': { prefix: ';', sep: ';', named: true, ifEmpty: '', reservedEncode: false },
  '?': { prefix: '?', sep: '&', named: true, ifEmpty: '=', reservedEncode: false },
  '&': { prefix: '&', sep: '&', named: true, ifEmpty: '=', reservedEncode: false },
};

function percentEncodeChar(char) {
  const bytes = Buffer.from(char, 'utf8');
  let out = '';
  for (const byte of bytes) {
    out += `%${byte.toString(16).toUpperCase().padStart(2, '0')}`;
  }
  return out;
}

/** Keep unreserved chars, reserved chars and existing percent-triplets; encode everything else. */
function encodeReserved(str) {
  const chars = Array.from(str);
  let result = '';
  for (let i = 0; i < chars.length; i += 1) {
    const ch = chars[i];
    if (ch === '%' && chars[i + 1] !== undefined && chars[i + 2] !== undefined && HEX.test(chars[i + 1]) && HEX.test(chars[i + 2])) {
      result += `%${chars[i + 1]}${chars[i + 2]}`;
      i += 2;
      continue;
    }
    if (UNRESERVED.test(ch) || RESERVED_CHARS.has(ch)) {
      result += ch;
    } else {
      result += percentEncodeChar(ch);
    }
  }
  return result;
}

/** Only unreserved characters survive; everything else, including existing percent signs, is encoded. */
function encodeStrict(str) {
  const chars = Array.from(str);
  let result = '';
  for (const ch of chars) {
    if (UNRESERVED.test(ch)) {
      result += ch;
    } else {
      result += percentEncodeChar(ch);
    }
  }
  return result;
}

function encodeValue(str, reservedEncode) {
  return reservedEncode ? encodeReserved(str) : encodeStrict(str);
}

function scalarString(value, name) {
  if (typeof value === 'string') return value;
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
}

function isUsable(value) {
  return value !== null && value !== undefined;
}

function collectPieces(name, value, explode, maxLength, op) {
  if (!isUsable(value)) return null;

  if (Array.isArray(value)) {
    const items = value.filter(isUsable);
    if (items.length === 0) return null;
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    if (explode) {
      return items.map((item) => {
        const encoded = encodeValue(scalarString(item, name), op.reservedEncode);
        if (op.named) {
          return encoded === '' ? `${name}${op.ifEmpty}` : `${name}=${encoded}`;
        }
        return encoded;
      });
    }
    const joined = items.map((item) => encodeValue(scalarString(item, name), op.reservedEncode)).join(',');
    return [op.named ? `${name}=${joined}` : joined];
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value).filter(([, v]) => isUsable(v));
    if (entries.length === 0) return null;
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    if (explode) {
      return entries.map(([key, v]) => {
        const encodedKey = encodeValue(key, op.reservedEncode);
        const encodedValue = encodeValue(scalarString(v, name), op.reservedEncode);
        if (op.named && encodedValue === '') {
          return `${encodedKey}${op.ifEmpty}`;
        }
        return `${encodedKey}=${encodedValue}`;
      });
    }
    const flat = [];
    for (const [key, v] of entries) {
      flat.push(encodeValue(key, op.reservedEncode));
      flat.push(encodeValue(scalarString(v, name), op.reservedEncode));
    }
    const joined = flat.join(',');
    return [op.named ? `${name}=${joined}` : joined];
  }

  let str = scalarString(value, name);
  if (maxLength !== null) {
    str = Array.from(str).slice(0, maxLength).join('');
  }
  const encoded = encodeValue(str, op.reservedEncode);
  if (op.named) {
    return [encoded === '' ? `${name}${op.ifEmpty}` : `${name}=${encoded}`];
  }
  return [encoded];
}

function expandExpression(expr, variables) {
  const op = OPERATORS[expr.operator];
  const pieces = [];
  for (const spec of expr.variables) {
    const has = Object.prototype.hasOwnProperty.call(variables, spec.name);
    const value = has ? variables[spec.name] : undefined;
    const contributed = collectPieces(spec.name, value, spec.explode, spec.maxLength, op);
    if (contributed) pieces.push(...contributed);
  }
  if (pieces.length === 0) return '';
  return op.prefix + pieces.join(op.sep);
}

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  if (variables === null || typeof variables !== 'object') {
    throw new UriTemplateError('variables must be an object');
  }
  const parts = parse(template);
  let result = '';
  for (const part of parts) {
    if (part.type === 'literal') {
      result += encodeReserved(part.value);
    } else {
      result += expandExpression(part, variables);
    }
  }
  return result;
}
